// Purchasing power: GDP per capita and population from the World Bank (free, no key)
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const get = async (ind) => {
    try {
      const r = await this.helpers.httpRequest({ url: `https://api.worldbank.org/v2/country/${m.iso}/indicator/${ind}?format=json&mrnev=1`, json: true });
      return r?.[1]?.[0]?.value ?? null;
    } catch (e) { return null; }
  };
  out.push({ json: { ...m, gdpPerCapita: await get('NY.GDP.PCAP.CD'), population: await get('SP.POP.TOTL') } });
}
return out;

// Search demand: 12-month Google Trends interest per market via SerpAPI
const key = $('Market brief').first().json.serpapiKey;
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  let interest = null, growth = null;
  if (key) {
    try {
      const r = await this.helpers.httpRequest({
        url: 'https://serpapi.com/search.json',
        qs: { engine: 'google_trends', q: m.keyword, geo: m.iso, date: 'today 12-m', api_key: key },
        json: true,
      });
      const pts = (r.interest_over_time?.timeline_data || []).map(p => p.values?.[0]?.extracted_value ?? 0);
      if (pts.length >= 8) {
        const avg = a => a.reduce((s, v) => s + v, 0) / a.length;
        const first = avg(pts.slice(0, 12)), last = avg(pts.slice(-12));
        interest = Math.round(avg(pts));
        growth = first > 0 ? Math.round(((last - first) / first) * 100) : null;
      }
    } catch (e) {}
  }
  out.push({ json: { ...m, searchInterest: interest, searchGrowthPct: growth } });
}
return out;

// Consumer buzz: Reddit posts in the last year mentioning the keyword and the market
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  let posts = 0, engagement = 0;
  try {
    const r = await this.helpers.httpRequest({
      url: 'https://www.reddit.com/search.json',
      qs: { q: `${m.keyword} ${m.name}`, t: 'year', limit: 100 },
      headers: { 'User-Agent': 'market-radar-n8n/1.0' },
      json: true,
    });
    const kids = r?.data?.children || [];
    posts = kids.length;
    engagement = kids.reduce((s, k) => s + (k.data?.score || 0) + (k.data?.num_comments || 0), 0);
  } catch (e) {}
  out.push({ json: { ...m, buzzPosts: posts, buzzEngagement: engagement } });
}
return out;

// Opportunity score (0 to 100): demand 35%, buzz 25%, purchasing power 25%, low competition 15%
const rows = $input.all().map(i => i.json);
const norm = (key, invert = false) => {
  const vals = rows.map(r => r[key]).filter(v => typeof v === 'number');
  const min = Math.min(...vals), max = Math.max(...vals);
  return r => {
    const v = r[key];
    if (typeof v !== 'number' || max === min) return 0.5;
    const n = (v - min) / (max - min);
    return invert ? 1 - n : n;
  };
};
const demand = norm('searchGrowthPct'), interest = norm('searchInterest');
const buzz = norm('buzzEngagement'), wealth = norm('gdpPerCapita'), comp = norm('competitors', true);
return rows
  .map(r => {
    const d = (demand(r) + interest(r)) / 2;
    const score = Math.round(100 * (0.35 * d + 0.25 * buzz(r) + 0.25 * wealth(r) + 0.15 * comp(r)));
    const tier = score >= 60 ? 'Enter now' : score >= 40 ? 'Watch' : 'Not yet';
    return { ...r, opportunityScore: score, tier, scoredAt: new Date().toISOString().slice(0, 10) };
  })
  .sort((a, b) => b.opportunityScore - a.opportunityScore)
  .map(json => ({ json }));

