// Turn Claude's answer into one tidy row for the sheet
const scored = $('Worth entering?').all(0, 0);
return $input.all().map((item, i) => {
  const m = scored[i]?.json || {};
  let s = {};
  try {
    const text = item.json.content?.[0]?.text || '{}';
    s = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
  } catch (e) { s = { positioning: item.json.content?.[0]?.text || '' }; }
  const list = v => Array.isArray(v) ? v.join('; ') : (v || '');
  return { json: {
    date: m.scoredAt, market: m.name, product: m.product, score: m.opportunityScore, tier: m.tier,
    targetSegment: s.targetSegment || '', positioning: s.positioning || '', pricing: s.pricing || '',
    channels: list(s.channels), partnerships: list(s.partnerships),
    launch_0_to_1: s.launch_0_to_1 || '', scale_1_to_10: s.scale_1_to_10 || '', scale_10_to_100: s.scale_10_to_100 || '',
    kpis: list(s.kpis), risks: list(s.risks),
  }};
});

// Keep the markets that are not ready yet, with the reason they scored low
return $input.all().map(i => ({ json: {
  date: i.json.scoredAt, market: i.json.name, product: i.json.product, score: i.json.opportunityScore, tier: i.json.tier,
  searchGrowthPct: i.json.searchGrowthPct, buzzEngagement: i.json.buzzEngagement, gdpPerCapita: i.json.gdpPerCapita, competitors: i.json.competitors,
}}));
